#!/usr/bin/env node
// Copy public/ and .next/static/ into the Next.js standalone output so Railway
// (and any Node runtime) can serve static assets + client chunks from a single dir.
// Next does not copy these automatically when output: 'standalone' is set.
import { cpSync, existsSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const cwd = process.cwd()
const standaloneRoot = join(cwd, '.next', 'standalone')

if (!existsSync(standaloneRoot)) {
  console.error('[postbuild] .next/standalone not found — is output:"standalone" set in next.config.ts?')
  process.exit(1)
}

// Next standalone may nest the server under the project path (reflects CWD).
// Find the directory that contains server.js.
function findServerDir(root) {
  if (existsSync(join(root, 'server.js'))) return root
  const { readdirSync, statSync } = require('node:fs')
  const entries = readdirSync(root, { withFileTypes: true })
  for (const e of entries) {
    if (!e.isDirectory()) continue
    const hit = findServerDir(join(root, e.name))
    if (hit) return hit
  }
  return null
}

// Simple, no require()
function walk(dir) {
  const { readdirSync, existsSync: ex } = require('node:fs')
  if (!ex(dir)) return null
  if (ex(join(dir, 'server.js'))) return dir
  for (const name of readdirSync(dir)) {
    const child = join(dir, name)
    const { statSync } = require('node:fs')
    try {
      if (!statSync(child).isDirectory()) continue
      const hit = walk(child)
      if (hit) return hit
    } catch {}
  }
  return null
}

const serverDir = walk(standaloneRoot)
if (!serverDir) {
  console.error('[postbuild] server.js not found inside .next/standalone — aborting')
  process.exit(1)
}

// Copy public/ → <serverDir>/public
const publicSrc = join(cwd, 'public')
if (existsSync(publicSrc)) {
  cpSync(publicSrc, join(serverDir, 'public'), { recursive: true })
  console.log(`[postbuild] copied public/ → ${serverDir}/public`)
}

// Copy .next/static/ → <serverDir>/.next/static
const staticSrc = join(cwd, '.next', 'static')
if (existsSync(staticSrc)) {
  const dest = join(serverDir, '.next', 'static')
  mkdirSync(join(serverDir, '.next'), { recursive: true })
  cpSync(staticSrc, dest, { recursive: true })
  console.log(`[postbuild] copied .next/static → ${dest}`)
}

console.log('[postbuild] standalone bundle ready')

