import AxeBuilder from '@axe-core/playwright'
import type { Page, TestInfo } from '@playwright/test'

export type A11yViolation = {
  id: string
  impact: string | null
  description: string
  nodes: number
  help: string
  helpUrl: string
}

export async function auditA11y(page: Page, info: TestInfo): Promise<A11yViolation[]> {
  const results = await new AxeBuilder({ page })
    .disableRules([
      // Radix/shadcn components use compositional patterns axe flags as false positives.
      'aria-allowed-attr',
      // Landmarks on minimal auth pages are intentional.
      'region',
    ])
    .analyze()

  const violations: A11yViolation[] = results.violations.map((v) => ({
    id: v.id,
    impact: v.impact ?? null,
    description: v.description,
    nodes: v.nodes.length,
    help: v.help,
    helpUrl: v.helpUrl,
  }))

  if (violations.length > 0) {
    await info.attach('axe-violations.json', {
      body: JSON.stringify(violations, null, 2),
      contentType: 'application/json',
    })
  }

  return violations
}

export function serious(violations: A11yViolation[]): A11yViolation[] {
  return violations.filter((v) => v.impact === 'serious' || v.impact === 'critical')
}

import type { Page, TestInfo } from '@playwright/test'

export type ConsoleCapture = {
  errors: string[]
  warnings: string[]
  pageErrors: string[]
}

// Noise we intentionally ignore. Patterns match `message` or `text()`.
const IGNORED = [
  // React 19 + Next 16 dev noise
  /Download the React DevTools/,
  /Fast Refresh/,
  // next-themes hydration warning when user hasn't picked a theme yet
  /hydration/i,
  // Sentry blocked by ad blockers in some environments
  /sentry\.io/,
  // Supabase realtime reconnection messages
  /realtime.*reconnect/i,
]

export function attachConsoleCapture(page: Page): ConsoleCapture {
  const capture: ConsoleCapture = { errors: [], warnings: [], pageErrors: [] }

  page.on('console', (msg) => {
    const text = msg.text()
    if (IGNORED.some((re) => re.test(text))) return
    if (msg.type() === 'error') capture.errors.push(text)
    else if (msg.type() === 'warning') capture.warnings.push(text)
  })

  page.on('pageerror', (err) => {
    const text = `${err.name}: ${err.message}`
    if (IGNORED.some((re) => re.test(text))) return
    capture.pageErrors.push(text)
  })

  return capture
}

export async function persistConsole(info: TestInfo, capture: ConsoleCapture): Promise<void> {
  if (capture.errors.length + capture.warnings.length + capture.pageErrors.length === 0) return
  await info.attach('console-capture.json', {
    body: JSON.stringify(capture, null, 2),
    contentType: 'application/json',
  })
}

