import { chromium, type FullConfig } from '@playwright/test'
import { createClient } from '@supabase/supabase-js'
import fs from 'node:fs'
import path from 'node:path'
import { config as loadEnv } from 'dotenv'

loadEnv({ path: path.resolve(process.cwd(), '.env.local') })

const AUTH_DIR = path.resolve(process.cwd(), 'e2e/.auth')
const STORAGE_PATH = path.join(AUTH_DIR, 'user.json')
const META_PATH = path.join(AUTH_DIR, 'user.json.meta.json')

export default async function globalSetup(config: FullConfig): Promise<void> {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY
  const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

  if (!supabaseUrl || !serviceRoleKey || !anonKey) {
    throw new Error(
      '[global-setup] Missing Supabase env vars. Ensure NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY, and SUPABASE_SERVICE_ROLE_KEY are set in .env.local'
    )
  }

  fs.mkdirSync(AUTH_DIR, { recursive: true })

  const timestamp = Date.now()
  const email = `playwright-${timestamp}@convertscan.test`
  const password = `PlaywrightTest!${timestamp}`

  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  })

  const { data: created, error: createError } = await admin.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
    user_metadata: { full_name: 'Playwright Test', playwright: true },
  })

  if (createError || !created?.user) {
    throw new Error(`[global-setup] Failed to create test user: ${createError?.message ?? 'unknown error'}`)
  }

  const userId = created.user.id

  // Wait briefly for the on_auth_user_created trigger (if present) to insert the profile row.
  await new Promise((r) => setTimeout(r, 800))

  // Ensure a profile row exists with a sensible plan for tests.
  const { error: upsertErr } = await admin
    .from('profiles')
    .upsert(
      {
        id: userId,
        email,
        full_name: 'Playwright Test',
        plan: 'growth',
        role: 'admin',
        scans_used: 0,
        scan_limit: 25,
      },
      { onConflict: 'id' }
    )

  if (upsertErr) {
    // Non-fatal — some schemas omit columns. Log but continue.
    console.warn(`[global-setup] profile upsert warning: ${upsertErr.message}`)
  }

  const baseURL = config.projects[0]?.use?.baseURL ?? 'http://localhost:3000'

  // Sign in via the actual app to produce a cookie-based session the middleware recognises.
  const browser = await chromium.launch()
  const context = await browser.newContext({ baseURL })
  const page = await context.newPage()
  await page.goto(`${baseURL}/login`, { waitUntil: 'domcontentloaded' })

  await page.fill('input[type="email"], input[name="email"]', email)
  await page.fill('input[type="password"], input[name="password"]', password)

  const submitButton = page.locator('button[type="submit"]').first()
  await Promise.all([
    page.waitForURL((url) => !url.pathname.startsWith('/login'), { timeout: 20_000 }),
    submitButton.click(),
  ]).catch((err) => {
    throw new Error(`[global-setup] Login did not redirect off /login. Check signup form selectors or Supabase response. Underlying: ${err instanceof Error ? err.message : String(err)}`)
  })

  await context.storageState({ path: STORAGE_PATH })
  await browser.close()

  fs.writeFileSync(
    META_PATH,
    JSON.stringify({ userId, email, password, createdAt: new Date().toISOString() }, null, 2)
  )

  console.log(`[global-setup] Test user created: ${email} (id=${userId})`)
}

