import { createClient } from '@supabase/supabase-js'
import fs from 'node:fs'
import path from 'node:path'
import { config as loadEnv } from 'dotenv'

loadEnv({ path: path.resolve(process.cwd(), '.env.local') })

const META_PATH = path.resolve(process.cwd(), 'e2e/.auth/user.json.meta.json')

export default async function globalTeardown(): Promise<void> {
  if (!fs.existsSync(META_PATH)) {
    console.log('[global-teardown] No test-user meta file — nothing to clean up.')
    return
  }

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!supabaseUrl || !serviceRoleKey) {
    console.warn('[global-teardown] Supabase env missing; skipping cleanup.')
    return
  }

  const meta = JSON.parse(fs.readFileSync(META_PATH, 'utf-8')) as { userId: string; email: string }
  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  })

  const { error } = await admin.auth.admin.deleteUser(meta.userId)
  if (error) {
    console.warn(`[global-teardown] Failed to delete user ${meta.userId}: ${error.message}`)
  } else {
    console.log(`[global-teardown] Deleted test user: ${meta.email}`)
  }

  try {
    fs.unlinkSync(META_PATH)
  } catch {
    /* ignore */
  }
}

