import { test, expect } from '@playwright/test'
import { ALL_ROUTES, PUBLIC_ROUTES } from './helpers/routes'
import {
  setTheme,
  applyThemeToCurrentPage,
  screenshotPage,
  waitForPageStable,
  expectNoBrokenRender,
  type Theme,
} from './helpers/visual'
import { auditA11y, serious } from './helpers/a11y'
import { attachConsoleCapture, persistConsole } from './helpers/console'

const THEMES: Theme[] = ['light', 'dark']

/**
 * Visual sweep: loads every route × every theme at the current viewport (controlled
 * by Playwright project). Captures screenshots, a11y violations, console errors.
 *
 * Authenticated and admin routes use the storage state from global-setup.
 */

test.describe('visual sweep — public routes', () => {
  for (const route of PUBLIC_ROUTES) {
    for (const theme of THEMES) {
      test(`${route.label} (${theme})`, async ({ page }, info) => {
        const console = attachConsoleCapture(page)
        await setTheme(page, theme)
        await page.goto(route.path, { waitUntil: 'domcontentloaded' })
        await applyThemeToCurrentPage(page, theme)
        await waitForPageStable(page)
        await expectNoBrokenRender(page)

        const viewport = info.project.name.replace('-chrome', '')
        await screenshotPage(page, info, { route: route.label, theme, viewport })

        const violations = await auditA11y(page, info)
        const seriousViolations = serious(violations)
        if (seriousViolations.length > 0) {
          await info.attach('a11y-serious.json', {
            body: JSON.stringify(seriousViolations, null, 2),
            contentType: 'application/json',
          })
        }

        await persistConsole(info, console)
        expect(seriousViolations, `serious a11y violations on ${route.path}`).toHaveLength(0)
        expect(console.pageErrors, `uncaught page errors on ${route.path}`).toHaveLength(0)
      })
    }
  }
})

test.describe('visual sweep — authed routes', () => {
  test.use({ storageState: 'e2e/.auth/user.json' })

  const authedAndAdmin = ALL_ROUTES.filter((r) => r.auth !== 'public')

  for (const route of authedAndAdmin) {
    for (const theme of THEMES) {
      test(`${route.label} (${theme})`, async ({ page }, info) => {
        const console = attachConsoleCapture(page)
        await setTheme(page, theme)
