      })
    }
  }
})

import { test, expect } from '@playwright/test'
import { attachConsoleCapture, persistConsole } from './helpers/console'

test.describe('auth flow', () => {
  test('root redirects unauthenticated visitor to /login', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    const response = await page.goto('/', { waitUntil: 'domcontentloaded' })
    expect(response?.status(), 'navigation status').toBeLessThan(500)
    await expect(page).toHaveURL(/\/login/, { timeout: 10_000 })
    await persistConsole(info, console)
  })

  test('login form renders required fields', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/login')
    await expect(page.locator('input[type="email"], input[name="email"]').first()).toBeVisible()
    await expect(page.locator('input[type="password"], input[name="password"]').first()).toBeVisible()
    await expect(page.locator('button[type="submit"]').first()).toBeVisible()
    await persistConsole(info, console)
  })

  test('signup form renders', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/signup')
    await expect(page.locator('input[type="email"], input[name="email"]').first()).toBeVisible()
    await expect(page.locator('input[type="password"], input[name="password"]').first()).toBeVisible()
    await persistConsole(info, console)
  })

  test('forgot-password page reachable', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/forgot-password')
    await expect(page.locator('input[type="email"], input[name="email"]').first()).toBeVisible()
    await persistConsole(info, console)
  })

  test.describe('authed session persists', () => {
    test.use({ storageState: 'e2e/.auth/user.json' })

    test('dashboard renders for authed user and session survives reload', async ({ page }, info) => {
      const console = attachConsoleCapture(page)
      await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })
      await expect(page).toHaveURL(/\/dashboard/, { timeout: 10_000 })
      await page.reload()
      await expect(page).toHaveURL(/\/dashboard/, { timeout: 10_000 })
      await persistConsole(info, console)
      expect(console.pageErrors).toHaveLength(0)
    })
  })
})

