import { test, expect } from '@playwright/test'
import { attachConsoleCapture, persistConsole } from './helpers/console'

test.use({ storageState: 'e2e/.auth/user.json' })

test.describe('scan flow', () => {
  test('scan page renders URL input and device selector', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/scan', { waitUntil: 'domcontentloaded' })
    await expect(page.locator('input[type="url"], input[placeholder*="https"], input[placeholder*="URL" i]').first()).toBeVisible({ timeout: 10_000 })
    await persistConsole(info, console)
    expect(console.pageErrors).toHaveLength(0)
  })

  test('submitting a URL keeps the user on /scan and does not 500', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/scan', { waitUntil: 'domcontentloaded' })
    const urlInput = page.locator('input[type="url"], input[placeholder*="https"], input[placeholder*="URL" i]').first()
    await urlInput.fill('https://example.com')
    // Try to click the main CTA. If the app blocks for any reason (limits, validation), we still expect no crash.
    const submit = page.locator('button[type="submit"], button:has-text("Analyze"), button:has-text("Scan"), button:has-text("Start")').first()
    if (await submit.isVisible({ timeout: 2_000 }).catch(() => false)) {
      await submit.click().catch(() => undefined)
    }
    // Either we remain on /scan (loading state) or we navigate to a report — both acceptable.
    await page.waitForTimeout(2_000)
    const url = new URL(page.url())
    expect(['/scan', '/reports']).toContainEqual(url.pathname.split('/').slice(0, 2).join('/'))
    await persistConsole(info, console)
  })
})

