import { test, expect } from '@playwright/test'
import { attachConsoleCapture, persistConsole } from './helpers/console'

test.use({ storageState: 'e2e/.auth/user.json' })

test.describe('navigation flows', () => {
  test('Cmd+K opens command palette', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(500)
    await page.keyboard.press('Meta+K')
    // CommandPalette uses cmdk which renders a dialog with role=dialog or data-cmdk-root.
    const paletteVisible = await page
      .locator('[cmdk-root], [role="dialog"]:has([cmdk-input], input[placeholder*="Search" i], input[placeholder*="Type" i])')
      .first()
      .isVisible({ timeout: 3_000 })
      .catch(() => false)

    // Fallback: try Ctrl+K for non-mac shortcut
    if (!paletteVisible) {
      await page.keyboard.press('Control+K')
    }
    const finalVisible = await page
      .locator('[cmdk-root], [role="dialog"]')
      .first()
      .isVisible({ timeout: 3_000 })
      .catch(() => false)
    await persistConsole(info, console)
    expect(finalVisible, 'Command palette did not open on Cmd+K or Ctrl+K').toBe(true)
  })

  test('sidebar renders primary nav items', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })
    // shadcn Sidebar renders nav links; match by href.
    const dashboardLink = page.locator('aside a[href="/dashboard"], nav a[href="/dashboard"]').first()
    await expect(dashboardLink).toBeVisible({ timeout: 10_000 })
    const scanLink = page.locator('aside a[href="/scan"], nav a[href="/scan"]').first()
    await expect(scanLink).toBeVisible()
    const reportsLink = page.locator('aside a[href="/reports"], nav a[href="/reports"]').first()
    await expect(reportsLink).toBeVisible()
    await persistConsole(info, console)
  })

  test('clicking Reports link in sidebar navigates', async ({ page }, info) => {
    const console = attachConsoleCapture(page)
    await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })
    const reportsLink = page.locator('aside a[href="/reports"], nav a[href="/reports"]').first()
    await reportsLink.click()
    await expect(page).toHaveURL(/\/reports/, { timeout: 10_000 })
    await persistConsole(info, console)
  })
})

