import { test } from '@playwright/test'
import path from 'node:path'

test.use({ storageState: 'e2e/.auth/user.json' })

test('sidebar-overlap diagnostic: dashboard layout metrics', async ({ page }, info) => {
  await page.setViewportSize({ width: 1440, height: 900 })
  await page.goto('/dashboard', { waitUntil: 'domcontentloaded' })
  await page.waitForLoadState('networkidle', { timeout: 10_000 }).catch(() => undefined)
  await page.waitForTimeout(800)

  const metrics = await page.evaluate(() => {
    const byId = (id: string) => document.getElementById(id)
    const by = (sel: string) => document.querySelector(sel)

    const rect = (el: Element | null) => {
      if (!el) return null
      const r = (el as HTMLElement).getBoundingClientRect()
      const cs = getComputedStyle(el as HTMLElement)
      return {
        x: r.x,
        y: r.y,
        width: r.width,
        height: r.height,
        right: r.right,
        display: cs.display,
        position: cs.position,
        flexDirection: cs.flexDirection,
        marginLeft: cs.marginLeft,
      }
    }

    const body = document.body
    const sidebarProvider = by('[class*="group/sidebar-wrapper"]')
    const peerWrapper = by('.group.peer, [data-state][data-side]') // sidebar peer wrapper
    const sidebarVisible = by('[data-sidebar="sidebar"]')?.parentElement ?? null // the fixed div wrapper
    const sidebarInner = by('[data-sidebar="sidebar"]')
    const inset = document.querySelector('main') // SidebarInset renders <main>
    const mainContent = byId('main-content')
    const heading = Array.from(document.querySelectorAll('h1, h2')).find((el) =>
      /welcome back|yash/i.test(el.textContent || '')
    )

    return {
      viewport: { w: window.innerWidth, h: window.innerHeight },
      body: rect(body),
      sidebarProvider: rect(sidebarProvider),
      peerWrapper: rect(peerWrapper),
      sidebarVisibleWrapper: rect(sidebarVisible),
      sidebarInner: rect(sidebarInner),
      sidebarInset: rect(inset),
      mainContent: rect(mainContent),
      headingRect: rect(heading ?? null),
      headingText: heading?.textContent?.slice(0, 80) ?? null,
      sidebarProviderClass: sidebarProvider?.className ?? null,
      peerWrapperClass: peerWrapper?.className ?? null,
      insetTag: inset?.tagName ?? null,
      insetClass: inset?.className ?? null,
    }
  })

  console.log('\n====== SIDEBAR LAYOUT DIAGNOSTIC ======')
  console.log(JSON.stringify(metrics, null, 2))
  console.log('====== END DIAGNOSTIC ======\n')

  await page.screenshot({
    path: path.join('test-results', 'diagnose-dashboard.png'),
    fullPage: false,
  })
  await info.attach('diagnose-metrics.json', {
    body: JSON.stringify(metrics, null, 2),
    contentType: 'application/json',
  })
})

